642→    if (name) payload.name = name;
643→
644→    fetch(API_BASE + "/api/waitlist", {
645→      method: "POST",
646→      headers: { "Content-Type": "application/json" },
647→      body: JSON.stringify(payload),
648→    })
649→      .then(function (r) { return r.json(); })
