654→            '<p style="font-size:13px;margin:6px 0 0;color:#008060">' +
655→            "\u2713 Your request has been submitted! We\u2019ll notify you when delivery is available." +
656→            "</p>";
657→        } else {
658→          wBtn.disabled = false;
659→          wBtn.textContent = "Submit Request";
660→        }
661→      })
662→      .catch(function () {
663→        wBtn.disabled = false;
664→        wBtn.textContent = "Submit Request";
665→      });
666→  }
