function joinWaitlist(zip, email, name, wBtn) {
  wBtn.disabled = true;
  var wBtnIcon = wBtn.querySelector('.zcc-wl-btn-icon');
  var wBtnLabel = wBtn.querySelector('.zcc-wl-btn-label');
  if (wBtnIcon) wBtnIcon.innerHTML = ICONS.spinner;
  if (wBtnLabel) wBtnLabel.textContent = 'Submitting\u2026';
  if (!wBtnIcon && !wBtnLabel) wBtn.textContent = 'Submitting\u2026';

  var payload = { shop: SHOP, zip: zip, email: email };
  if (name) payload.name = name;

  fetch(API_BASE + "/api/waitlist", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  })
    .then(function (r) { return r.json(); })
    .then(function (data) {
      var wlEl = wBtn.closest(".zcc-wl");
      if (data.success) {
        if (wlEl) wlEl.innerHTML =
          '<div class="zcc-wl-success">' +
          '<span class="zcc-wl-success-icon">' + ICONS.checkmark + '</span>' +
          '<span>Your request has been submitted! We\u2019ll notify you when delivery is available.</span>' +
          '</div>';
      } else {
        wBtn.disabled = false;
        if (wBtnIcon) wBtnIcon.innerHTML = ICONS.mail;
        if (wBtnLabel) wBtnLabel.textContent = 'Submit Request';
        if (!wBtnIcon && !wBtnLabel) wBtn.textContent = 'Submit Request';
      }
    })
    .catch(function () {
      wBtn.disabled = false;
      if (wBtnIcon) wBtnIcon.innerHTML = ICONS.mail;
      if (wBtnLabel) wBtnLabel.textContent = 'Submit Request';
      if (!wBtnIcon && !wBtnLabel) wBtn.textContent = 'Submit Request';
    });
}

